const { siraylaIsle, tekrarDene, say, ortalama, grupla } = require("./islem.js");

(async () => {
  // siraylaIsle: sıralı çalışma
  let order = [];
  const r = await siraylaIsle([1,2,3], async (x) => { order.push(x); return x*10; });
  console.log("siraylaIsle order:", JSON.stringify(order)); // [1,2,3]
  console.log("siraylaIsle result:", JSON.stringify(r)); // [10,20,30]
  const empty = await siraylaIsle([], x => x);
  console.log("siraylaIsle empty:", JSON.stringify(empty)); // []

  // tekrarDene: deneme=2 ile 0,1 çağrılmalı
  let count = 0;
  const res = await tekrarDene(async (i) => { count++; if (count < 2) throw new Error("bad"); return "ok"; }, 2);
  console.log("tekrarDene:", res, "count:", count); // ok, 2
  // Hepsi başarısız
  try { await tekrarDene(async () => { throw new Error("fail"); }, 3); console.log("BOY"); } catch(e) { console.log("tekrarDene throw:", e.message); }

  // say
  console.log("say:", JSON.stringify(say(["a","b","a"]))); // {a:2,b:1}
  console.log("say empty:", JSON.stringify(say([]))); // {}
  console.log("say single:", JSON.stringify(say(["x"]))); // {x:1}

  // ortalama
  console.log("ortalama [2,4]:", ortalama([2,4])); // 3
  console.log("ortalama []:", ortalama([])); // 0
  console.log("ortalama [10]:", ortalama([10])); // 10

  // grupla
  console.log("grupla:", JSON.stringify(grupla([1,2,3,4,5,6], x => x % 2)));

  console.log("HERŞEY OK");
})();
'

